<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
$checks=0;
function finance_check(bool $ok,string $why): void { global $checks; if (!$ok) throw new RuntimeException($why); $checks++; }
function finance_rejects(callable $fn,string $why): void { try { $fn(); } catch (InvalidArgumentException $e) { finance_check(true,$why); return; } throw new RuntimeException($why); }
Db::init(':memory:');
$modules=Modules::discover(ROOT.'/app/Modules'); Migrator::run(array_merge([ROOT.'/app/Core/migrations'],array_map(fn($m)=>$m['path'].'/migrations',$modules)));
$plan=['month'=>'2026-10','income'=>'100000','bills'=>'20000','loan_payments'=>'10000','living'=>'30000','savings_percent'=>'15','investment_percent'=>'10','emergency_account_id'=>'2','emergency_months'=>'3'];
$math=FinancePlanningService::calculate($plan);
finance_check($math['available']===15000 && $math['savings']===15000 && $math['investments']===10000,'Salary plan arithmetic');
finance_check($math['suggested_savings']===15000 && $math['suggested_percent']===15.0,'Suggestion uses half of disposable remainder');
$tiny=FinancePlanningService::calculate(['income'=>'0.01','savings_percent'=>'50','investment_percent'=>'50']);
finance_check((int)round(($tiny['savings']+$tiny['investments'])*100)===1 && $tiny['available']===0,'Planner conserves fractional-cent splits');
finance_rejects(fn()=>FinancePlanningService::calculate(array_merge($plan,['savings_percent'=>'95','investment_percent'=>'10'])),'Over-100 rates rejected');
$deficit=FinancePlanningService::calculate(array_merge($plan,['bills'=>'100000']));
finance_check(!$deficit['affordable'] && $deficit['suggested_savings']===0,'Deficits do not recommend unattainable savings');
FinancePlanningService::savePlan($plan); FinancePlanningService::savePlan(array_merge($plan,['living'=>'30000']));
finance_check((int)Db::one('SELECT COUNT(*) n FROM salary_plans')['n']===1,'One plan per month');
finance_check((int)Db::one('SELECT COUNT(*) n FROM income')['n']===0 && (int)Db::one('SELECT COUNT(*) n FROM expenses')['n']===0,'Plan does not create fake transactions');
Db::run('UPDATE accounts SET balance=10000 WHERE id=2');
$saved=FinancePlanningService::plan('2026-10');
finance_check($saved['emergency_current']===10000.0 && $saved['emergency_target']===180000.0,'Emergency fund uses actual savings account balance and essential costs');
$series=FinancePlanningService::project($saved);
finance_check(count($series)===12 && $series[11]['month']==='2027-09' && $series[11]['savings']===180000 && $series[11]['investments']===120000,'Projection uses fixed contributions without invented growth');
finance_check($saved['savings_step_percent']===0 && $series[0]['monthly_savings']===15000 && $series[11]['applied_savings_percent']===15,'Existing plans default to constant savings');
finance_check(FinancePlanningService::calculate(array_merge($plan,['savings_step_percent'=>'']))['savings_step_percent']===0,'An empty optional increase defaults to zero');
$progressive=array_merge($plan,['savings_step_percent'=>'5']); FinancePlanningService::savePlan($progressive);
$growing=FinancePlanningService::project(FinancePlanningService::plan('2026-10'));
finance_check(FinancePlanningService::plan('2026-10')['savings_step_percent']===5,'Monthly percentage-point increase persists');
finance_check(array_column(array_slice($growing,0,4),'monthly_savings')===[15000,20000,25000,30000],'Savings contributions increase one step per month');
finance_check($growing[4]['requested_savings_percent']===35 && $growing[4]['applied_savings_percent']===30 && $growing[4]['capped'] && $growing[4]['affordability_cap_percent']===30,'Increases stop at the affordable rate after essentials and investment');
finance_check($growing[11]['savings']===330000 && $growing[11]['investments']===120000 && $growing[11]['available']===0,'Progression accumulates contributions without returns or overspending');
$centPlan=['month'=>'2026-10','income'=>'1.01','bills'=>'0.34','living'=>'0.11','savings_percent'=>'10','investment_percent'=>'13.37','savings_step_percent'=>'7.25'];
foreach (FinancePlanningService::project($centPlan) as $point) finance_check((int)round(($point['monthly_savings']+$point['monthly_investments']+$point['available']+0.45)*100)===101 && $point['available']>=0,'Progression preserves every cent within affordable limits');
$impossible=FinancePlanningService::project(array_merge($progressive,['bills'=>'100000']));
finance_check($impossible[0]['monthly_savings']===0 && !$impossible[0]['affordable'] && $impossible[0]['available']<0,'A basic-cost deficit remains visible instead of inventing affordable savings');
finance_rejects(fn()=>FinancePlanningService::savePlan(array_merge($plan,['savings_step_percent'=>'100.01'])),'Invalid monthly increase rejected');
finance_check(FinancePlanningService::plan('2026-10')['savings_step_percent']===5,'Invalid increase preserves saved plan');
FinancePlanningService::savePlan($plan);
$previousRules=Db::all('SELECT * FROM allocation_rules ORDER BY sort,id');
$investment=InvestmentService::create('Plan-linked investment','business','2026-01-01','');
finance_rejects(fn()=>FinancePlanningService::applyPlanAllocations('2026-10',1,1,$investment),'Plan requires a savings-kind account for positive savings');
finance_rejects(fn()=>FinancePlanningService::applyPlanAllocations('2026-10',1,2,null),'Plan requires an investment asset for positive investments');
finance_check(Db::all('SELECT * FROM allocation_rules ORDER BY sort,id')===$previousRules,'Invalid plan destinations preserve allocation rules');
FinancePlanningService::applyPlanAllocations('2026-10',1,2,$investment);
$cashBefore=(float)Db::one('SELECT balance FROM accounts WHERE id=1')['balance']; $savingsBefore=(float)Db::one('SELECT balance FROM accounts WHERE id=2')['balance'];
$linkedIncome=SalaryService::addIncome('2026-10-24','Plan-linked salary','100000');
finance_check((float)Db::one('SELECT amount FROM asset_transactions WHERE income_id=? AND asset_id=?',[$linkedIncome,$investment])['amount']===10000.0,'Applied salary plan sends the investment share directly into the chosen asset');
finance_check((float)Db::one('SELECT balance FROM accounts WHERE id=1')['balance']===$cashBefore+75000 && (float)Db::one('SELECT balance FROM accounts WHERE id=2')['balance']===$savingsBefore+15000,'Applied plan credits savings and spending once without double-counting the asset');
SalaryService::deleteIncome($linkedIncome);
finance_check(!Db::one('SELECT id FROM asset_transactions WHERE income_id=?',[$linkedIncome]) && (float)Db::one('SELECT balance FROM accounts WHERE id=1')['balance']===$cashBefore,'Deleting plan-linked income reverses its asset deposit and account credits');
SalaryService::saveRules(array_map(fn($rule)=>['name'=>$rule['name'],'percent'=>$rule['percent'],'account'=>$rule['target_id'],'asset'=>$rule['asset_target_id'],'active'=>$rule['active']],$previousRules));
finance_check(FinancePlanningService::nextDate('2026-01-31','monthly',31)==='2026-02-28' && FinancePlanningService::nextDate('2026-02-28','monthly',31)==='2026-03-31','End-of-month clamping keeps original anchor');
finance_check(FinancePlanningService::nextDate('2024-01-31','monthly',31)==='2024-02-29','Leap-year monthly clamping');
finance_check(FinancePlanningService::nextDate('2024-02-29','yearly',29)==='2025-02-28','Leap-year annual clamping');
$bill=FinancePlanningService::addObligation(['title'=>'Test bill','kind'=>'bill','amount'=>'250','due_date'=>'2026-01-31','interval'=>'monthly','account_id'=>'1','category_id'=>'1']);
$payment=FinancePlanningService::payObligation($bill,'2026-01-31','2026-01-31');
finance_check(FinancePlanningService::payObligation($bill,'2026-01-31','2026-02-01')===$payment && (int)Db::one('SELECT COUNT(*) n FROM financial_payments')['n']===1,'Duplicate payment does not create second expense');
finance_check(Db::one('SELECT due_date FROM financial_obligations WHERE id=?',[$bill])['due_date']==='2026-02-28','Bill date advances after payment');
FinancePlanningService::payObligation($bill,'2026-02-28','2026-02-28'); SalaryService::deleteExpense($payment);
finance_check(Db::one('SELECT due_date FROM financial_obligations WHERE id=?',[$bill])['due_date']==='2026-01-31','Expense reversal reopens original due date');
FinancePlanningService::payObligation($bill,'2026-01-31','2026-03-01');
finance_check(Db::one('SELECT due_date FROM financial_obligations WHERE id=?',[$bill])['due_date']==='2026-03-31','Repayment skips a later occurrence already paid');
$loan=FinancePlanningService::addObligation(['title'=>'Test loan','kind'=>'loan','amount'=>'1000','outstanding'=>'2500','due_date'=>'2026-01-31','interval'=>'monthly','account_id'=>'1','category_id'=>'1']);
FinancePlanningService::payObligation($loan,'2026-01-31','2026-01-31'); FinancePlanningService::payObligation($loan,'2026-02-28','2026-02-28');
$last=FinancePlanningService::payObligation($loan,'2026-03-31','2026-03-31');
$repaid=Db::one('SELECT * FROM financial_obligations WHERE id=?',[$loan]);
finance_check((float)$repaid['outstanding']===0.0 && !$repaid['active'] && (float)Db::one('SELECT amount FROM expenses WHERE id=?',[$last])['amount']===500.0,'Final loan payment clips to remaining principal and closes schedule');
SalaryService::deleteExpense($last); $reopened=Db::one('SELECT * FROM financial_obligations WHERE id=?',[$loan]);
finance_check((float)$reopened['outstanding']===500.0 && (int)$reopened['active']===1,'Reversing loan expense restores outstanding balance');
$recurrence=FinancePlanningService::addRecurrence(['title'=>'Actual monthly salary','kind'=>'income','amount'=>'100.01','next_date'=>'2026-01-31','interval'=>'monthly','income_type'=>'salary']);
finance_check(FinancePlanningService::processDue('2026-03-31')['processed']===0,'Paused schedules never auto-record');
FinancePlanningService::setRecurrence($recurrence,true); $run=FinancePlanningService::processDue('2026-03-31');
finance_check($run['processed']===3 && !$run['errors'] && (int)Db::one('SELECT COUNT(*) n FROM financial_occurrences')['n']===3,'Enabled recurrence catches up exactly once per due date');
finance_check(Db::one('SELECT next_date FROM financial_recurrences WHERE id=?',[$recurrence])['next_date']==='2026-04-30','Monthly catch-up advances anchored due date');
finance_check(FinancePlanningService::processDue('2026-03-31')['processed']===0,'Repeated processing is idempotent');
$generated=(int)Db::one('SELECT income_id FROM financial_occurrences WHERE recurrence_id=? ORDER BY id',[$recurrence])['income_id']; SalaryService::deleteIncome($generated);
finance_check(FinancePlanningService::processDue('2026-03-31')['processed']===0 && Db::one('SELECT income_id FROM financial_occurrences WHERE recurrence_id=? ORDER BY id',[$recurrence])['income_id']===null,'Removed generated entry is not silently recreated');
$daily=FinancePlanningService::addRecurrence(['title'=>'Daily subscription','kind'=>'expense','amount'=>'1.25','next_date'=>'2026-01-01','interval'=>'daily','active'=>1,'account_id'=>'1','category_id'=>'1']);
$limited=FinancePlanningService::processDue('2026-01-10',2);
finance_check($limited['processed']===2 && $limited['remaining']===1,'Catch-up limit bounds work per request');
FinancePlanningService::setRecurrence($daily,false);
Db::run("UPDATE allocation_rules SET target_type='asset',asset_target_id=NULL");
$failing=FinancePlanningService::addRecurrence(['title'=>'Invalid target salary','kind'=>'income','amount'=>'50','next_date'=>'2000-01-01','interval'=>'monthly','active'=>1]);
$before=(int)Db::one('SELECT COUNT(*) n FROM income')['n']; $failure=FinancePlanningService::processDue('2000-01-01');
finance_check(count($failure['errors'])===1 && !(int)Db::one('SELECT active FROM financial_recurrences WHERE id=?',[$failing])['active'],'Invalid recurrence pauses and reports its error');
finance_check((int)Db::one('SELECT COUNT(*) n FROM income')['n']===$before && !Db::one('SELECT id FROM financial_occurrences WHERE recurrence_id=?',[$failing]),'Failed recurrence rolls back income, allocations and occurrence');
Db::run("UPDATE allocation_rules SET target_type='account',asset_target_id=NULL");
SalaryService::addExpense('2026-10-22',1,1,'20','Week expense'); SalaryService::addExpense('2026-10-24',1,1,'30','Today expense');
$totals=FinancePlanningService::dailyWeeklyTotals('2026-10-24');
finance_check($totals['today']===30.0 && $totals['week']===50.0 && $totals['week_start']==='2026-10-19','Daily and ISO-week expense totals');
finance_check(count(FinancePlanningService::dueItems(365,'2026-01-01'))===2,'Financial reminders expose active bill and loan due dates');
Db::close(); echo "$checks finance planning checks passed.\n";
